// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.undoimport com.roshan.persona.brain.skill.AudioStreamimport com.roshan.persona.brain.skill.DndModeimport com.roshan.persona.brain.skill.LocationModeimport com.roshan.persona.brain.skill.RingerModeimport com.roshan.persona.brain.skill.SystemOperation/** * NOUS — System Operation Serializer (Module 10 v2 — PersistentUndoStack support). * * Serializes [SystemOperation] instances to/from compact JSON strings for * persistence in the [com.roshan.persona.database.entity.UndoActionEntity] * Room table. * * ## Why manual, not kotlinx.serialization? * * SystemOperation is a sealed interface with ~20 variants in Module 2's * package. Adding `@Serializable` to it would require a kotlinx-serialization * plugin in :feature:brain — a non-trivial refactor. A manual serializer is * simpler, has zero dependencies, and gives us full control over the wire * format (smaller JSON, no version drift). * * ## Format * * Each operation serializes to: * ```json * {"type":"SetTorch","on":true,"brightness":1.0} * ``` * * The `type` field is always present and identifies the variant. Field * names match the data class property names. Enums serialize as their * `name` string. * * ## Pre-state format * * Pre-states are arbitrary (could be Int, Boolean, Pair<AudioStream, Int>, * etc.). We serialize them as JSON too, with a `type` discriminator: * ```json * {"type":"Int","value":50} * {"type":"Boolean","value":true} * {"type":"Pair","first":"MEDIA","second":50} * ``` * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Persistent Undo Stack</a> */object SystemOperationSerializer {    // ─── Operation serialization ──────────────────────────────────────────    /** Serialize a [SystemOperation] to a JSON string. */    fun serializeOperation(operation: SystemOperation): String {        val type = operation::class.simpleName ?: error("Anonymous operation class")        val body = when (operation) {            is SystemOperation.SetTorch ->                "\"on\":${operation.on},\"brightness\":${operation.brightness}"            is SystemOperation.AdjustVolume ->                "\"delta\":${operation.delta},\"stream\":\"${operation.stream.name}\""            is SystemOperation.SetVolume ->                "\"level\":${operation.level},\"stream\":\"${operation.stream.name}\""            is SystemOperation.SetDisplayBrightness ->                "\"level\":${operation.level}"            is SystemOperation.AdjustDisplayBrightness ->                "\"delta\":${operation.delta}"            is SystemOperation.ScreenOn ->                ""  // No params — data object            is SystemOperation.ScreenOff ->                ""  // No params — data object            is SystemOperation.SetRingerMode ->                "\"mode\":\"${operation.mode.name}\""            is SystemOperation.SetAirplaneMode ->                "\"on\":${operation.on}"            is SystemOperation.SetWifi ->                "\"on\":${operation.on}"            is SystemOperation.SetBluetooth ->                "\"on\":${operation.on}"            is SystemOperation.OpenApp ->                "\"packageName\":\"${escape(operation.packageName)}\""            is SystemOperation.OpenUrl ->                "\"url\":\"${escape(operation.url)}\""            is SystemOperation.CopyToClipboard ->                "\"text\":\"${escape(operation.text)}\""            is SystemOperation.SetAlarm ->                "\"hour\":${operation.hour},\"minute\":${operation.minute}" +                    (operation.label?.let { ",\"label\":\"${escape(it)}\"" } ?: "")            is SystemOperation.SetTimer ->                "\"durationSeconds\":${operation.durationSeconds}" +                    (operation.label?.let { ",\"label\":\"${escape(it)}\"" } ?: "")            is SystemOperation.SendSms ->                "\"contact\":\"${escape(operation.contact)}\",\"message\":\"${escape(operation.message)}\""            is SystemOperation.MakeCall ->                "\"contact\":\"${escape(operation.contact)}\""            is SystemOperation.SetLocationMode ->                "\"mode\":\"${operation.mode.name}\""            is SystemOperation.SetTethering ->                "\"enabled\":${operation.enabled}"            is SystemOperation.SetNfc ->                "\"enabled\":${operation.enabled}"            is SystemOperation.LockScreen ->                ""            is SystemOperation.SetKeepScreenOn ->                "\"enabled\":${operation.enabled}"            is SystemOperation.SetDndMode ->                "\"mode\":\"${operation.mode.name}\""            is SystemOperation.SetBatterySaver ->                "\"enabled\":${operation.enabled}"            is SystemOperation.PostNotification ->                "\"id\":${operation.id},\"channelId\":\"${escape(operation.channelId)}\"," +                    "\"channelName\":\"${escape(operation.channelName)}\"," +                    "\"title\":\"${escape(operation.title)}\",\"text\":\"${escape(operation.text)}\""            is SystemOperation.Composite ->                "\"operations\":[${operation.operations.joinToString(",") { serializeOperation(it) }}]"        }        return if (body.isEmpty()) "{\"type\":\"$type\"}"        else "{\"type\":\"$type\",$body}"    }    /** Deserialize a JSON string back to a [SystemOperation]. */    fun deserializeOperation(json: String): SystemOperation {        val map = parseJsonObject(json)        val type = map["type"] as? String            ?: error("Missing 'type' field in operation JSON: $json")        return when (type) {            "SetTorch" -> SystemOperation.SetTorch(                on = (map["on"] as? Boolean) ?: false,                brightness = (map["brightness"] as? Number)?.toFloat() ?: 1.0f,            )            "AdjustVolume" -> SystemOperation.AdjustVolume(                delta = (map["delta"] as? Number ?: 0).toInt(),                stream = AudioStream.valueOf((map["stream"] as? String) ?: "MUSIC"),            )            "SetVolume" -> SystemOperation.SetVolume(                level = (map["level"] as? Number ?: 0).toInt(),                stream = AudioStream.valueOf((map["stream"] as? String) ?: "MUSIC"),            )            "SetDisplayBrightness" -> SystemOperation.SetDisplayBrightness(                level = (map["level"] as? Number ?: 0).toFloat(),            )            "AdjustDisplayBrightness" -> SystemOperation.AdjustDisplayBrightness(                delta = (map["delta"] as? Number ?: 0).toFloat(),            )            "ScreenOn" -> SystemOperation.ScreenOn            "ScreenOff" -> SystemOperation.ScreenOff            "SetRingerMode" -> SystemOperation.SetRingerMode(                mode = RingerMode.valueOf((map["mode"] as? String) ?: "NORMAL"),            )            "SetAirplaneMode" -> SystemOperation.SetAirplaneMode((map["on"] as? Boolean) ?: false)            "SetWifi" -> SystemOperation.SetWifi((map["on"] as? Boolean) ?: false)            "SetBluetooth" -> SystemOperation.SetBluetooth((map["on"] as? Boolean) ?: false)            "OpenApp" -> SystemOperation.OpenApp((map["packageName"] as? String) ?: "")            "OpenUrl" -> SystemOperation.OpenUrl((map["url"] as? String) ?: "")            "CopyToClipboard" -> SystemOperation.CopyToClipboard((map["text"] as? String) ?: "")            "SetAlarm" -> SystemOperation.SetAlarm(                hour = (map["hour"] as? Number ?: 0).toInt(),                minute = (map["minute"] as? Number ?: 0).toInt(),                label = map["label"] as? String,            )            "SetTimer" -> SystemOperation.SetTimer(                durationSeconds = (map["durationSeconds"] as? Number ?: 0).toLong(),                label = map["label"] as? String,            )            "SendSms" -> SystemOperation.SendSms(                contact = (map["contact"] as? String) ?: "",                message = map["message"] as String,            )            "MakeCall" -> SystemOperation.MakeCall((map["contact"] as? String) ?: "")            "SetLocationMode" -> SystemOperation.SetLocationMode(                mode = LocationMode.valueOf((map["mode"] as? String) ?: "NORMAL"),            )            "SetTethering" -> SystemOperation.SetTethering(map["enabled"] as Boolean)            "SetNfc" -> SystemOperation.SetNfc(map["enabled"] as Boolean)            "LockScreen" -> SystemOperation.LockScreen            "SetKeepScreenOn" -> SystemOperation.SetKeepScreenOn(map["enabled"] as Boolean)            "SetDndMode" -> SystemOperation.SetDndMode(                mode = DndMode.valueOf((map["mode"] as? String) ?: "NORMAL"),            )            "SetBatterySaver" -> SystemOperation.SetBatterySaver(map["enabled"] as Boolean)            "PostNotification" -> SystemOperation.PostNotification(                id = (map["id"] as? Number ?: 0).toInt(),                channelId = (map["channelId"] as? String) ?: "",                channelName = (map["channelName"] as? String) ?: "",                title = (map["title"] as? String) ?: "",                text = (map["text"] as? String) ?: "",            )            "Composite" -> {                val opsJson = map["operations"] as String                SystemOperation.Composite(parseOperationList(opsJson))            }            else -> error("Unknown operation type: $type")        }    }    // ─── Pre-state serialization ──────────────────────────────────────────    /** Serialize a pre-state value to a JSON string. */    fun serializePreState(preState: Any?): String? {        if (preState == null) return null        return when (preState) {            is Int -> "{\"type\":\"Int\",\"value\":$preState}"            is Long -> "{\"type\":\"Long\",\"value\":$preState}"            is Float -> "{\"type\":\"Float\",\"value\":$preState}"            is Double -> "{\"type\":\"Double\",\"value\":$preState}"            is Boolean -> "{\"type\":\"Boolean\",\"value\":$preState}"            is String -> "{\"type\":\"String\",\"value\":\"${escape(preState)}\"}"            is Pair<*, *> -> {                val first = serializePreStateValue(preState.first)                val second = serializePreStateValue(preState.second)                "{\"type\":\"Pair\",\"first\":$first,\"second\":$second}"            }            else -> "{\"type\":\"String\",\"value\":\"${escape(preState.toString())}\"}"        }    }    /** Deserialize a pre-state JSON string back to a value. */    fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = parseJsonObject(json)        val type = map["type"] as? String ?: return null        return when (type) {            "Int" -> (map["value"] as Number).toInt()            "Long" -> (map["value"] as Number).toLong()            "Float" -> (map["value"] as Number).toFloat()            "Double" -> (map["value"] as Number).toDouble()            "Boolean" -> map["value"] as Boolean            "String" -> map["value"] as String            "Pair" -> Pair(                map["first"]?.let { deserializePreStateValue(it as String) },                map["second"]?.let { deserializePreStateValue(it as String) },            )            else -> null        }    }    // ─── Helpers ──────────────────────────────────────────────────────────    private fun serializePreStateValue(value: Any?): String = when (value) {        null -> "null"        is String -> "\"${escape(value)}\""        is Enum<*> -> "\"${value.name}\""        is Int, is Long, is Float, is Double, is Boolean -> value.toString()        else -> "\"${escape(value.toString())}\""    }    private fun deserializePreStateValue(value: String): Any? = when {        value == "null" -> null        value.startsWith("\"") -> unescape(value.trim('"'))        value == "true" -> true        value == "false" -> false        value.toIntOrNull() != null -> value.toInt()        value.toLongOrNull() != null -> value.toLong()        value.toFloatOrNull() != null -> value.toFloat()        else -> value    }    private fun escape(s: String): String =        s.replace("\\", "\\\\").replace("\"", "\\\"")    private fun unescape(s: String): String =        s.replace("\\\"", "\"").replace("\\\\", "\\")    /**     * Minimal JSON object parser. Returns a Map<String, Any?> of top-level keys.     *     * For nested objects (e.g., Composite's operations list), the value is     * returned as a raw JSON string for the caller to parse further.     *     * Public so that per-handler [serializePreState] / [deserializePreState]     * overrides can re-use it (audit defect B fix).     */    fun parseJsonObject(json: String): Map<String, Any?> {        val result = mutableMapOf<String, Any?>()        val trimmed = json.trim()        if (!trimmed.startsWith("{") || !trimmed.endsWith("}")) {            error("Not a JSON object: $json")        }        val body = trimmed.substring(1, trimmed.length - 1)        var i = 0        while (i < body.length) {            // Skip whitespace + commas.            while (i < body.length && (body[i] == ',' || body[i].isWhitespace())) i++            if (i >= body.length) break            // Parse key.            if (body[i] != '"') error("Expected '\"' at position $i in $body")            val keyEnd = body.indexOf('"', startIndex = i + 1)            val key = body.substring(i + 1, keyEnd)            i = keyEnd + 1            // Skip colon.            while (i < body.length && body[i] != ':') i++            i++  // skip ':'            // Skip whitespace.            while (i < body.length && body[i].isWhitespace()) i++            if (i >= body.length) break            // Parse value.            val (value, next) = parseJsonValue(body, i)            result[key] = value            i = next        }        return result    }    /** Parse a JSON value starting at [start]. Returns (value, nextIndex). */    fun parseJsonValue(s: String, start: Int): Pair<Any?, Int> {        if (start >= s.length) return null to start        return when (s[start]) {            '"' -> {                val end = findStringEnd(s, start + 1)                unescape(s.substring(start + 1, end)) to (end + 1)            }            't' -> true to (start + 4)  // "true"            'f' -> false to (start + 5)  // "false"            'n' -> null to (start + 4)  // "null"            '[' -> {                val end = findBracketEnd(s, start, '[', ']')                // Return raw JSON string for array — caller parses further.                s.substring(start, end + 1) to (end + 1)            }            '{' -> {                val end = findBracketEnd(s, start, '{', '}')                s.substring(start, end + 1) to (end + 1)            }            else -> {                // Number.                val end = start + s.substring(start).takeWhile { it.isDigit() || it == '.' || it == '-' }                    .length                val numStr = s.substring(start, end)                val num: Any = numStr.toLongOrNull() ?: numStr.toDoubleOrNull() ?: 0                num to end            }        }    }    private fun findStringEnd(s: String, start: Int): Int {        var i = start        while (i < s.length) {            if (s[i] == '\\') { i += 2; continue }            if (s[i] == '"') return i            i++        }        error("Unterminated string in JSON: $s")    }    private fun findBracketEnd(s: String, start: Int, open: Char, close: Char): Int {        var depth = 0        var i = start        while (i < s.length) {            when (s[i]) {                open -> depth++                close -> {                    depth--                    if (depth == 0) return i                }            }            i++        }        error("Unmatched '$open' in JSON: $s")    }    /** Parse a JSON array of operations (for Composite). */    private fun parseOperationList(json: String): List<SystemOperation> {        val trimmed = json.trim()        if (!trimmed.startsWith("[") || !trimmed.endsWith("]")) return emptyList()        val body = trimmed.substring(1, trimmed.length - 1)        if (body.isBlank()) return emptyList()        val ops = mutableListOf<SystemOperation>()        var i = 0        while (i < body.length) {            while (i < body.length && (body[i] == ',' || body[i].isWhitespace())) i++            if (i >= body.length) break            if (body[i] != '{') break            val end = findBracketEnd(body, i, '{', '}')            ops.add(deserializeOperation(body.substring(i, end + 1)))            i = end + 1        }        return ops    }}